using System;
using UnityEngine;

namespace Game.Map
{
    #region Terrain Type

    /// <summary>
    /// 迷路内のマスの地形を表す列挙型。
    /// </summary>
    public enum MazeTerrainType
    {
        /// <summary>
        /// 移動可能な通常の床。
        /// </summary>
        Floor = 0,

        /// <summary>
        /// 移動および破壊が不可能な通常の壁。
        /// </summary>
        Wall = 1,

        /// <summary>
        /// 特定の能力などによって破壊可能な壁。
        /// </summary>
        BreakableWall = 2
    }

    #endregion

    #region Cell Flags

    /// <summary>
    /// 迷路内のマスが持つ配置物や属性を表す列挙型。
    ///
    /// Flags属性によって複数の属性を
    /// 同時に保持することができる。
    /// </summary>
    [Flags]
    public enum MazeCellFlags
    {
        /// <summary>
        /// 特別な属性を持たない状態。
        /// </summary>
        None = 0,

        /// <summary>
        /// 宝石が配置されている。
        /// </summary>
        Gem = 1 << 0,

        /// <summary>
        /// アイテムが配置されている。
        /// </summary>
        Item = 1 << 1,

        /// <summary>
        /// プレイヤーの初期出現地点。
        /// </summary>
        PlayerSpawn = 1 << 2,

        /// <summary>
        /// 敵キャラクターの出現地点。
        /// </summary>
        EnemySpawn = 1 << 3,

        /// <summary>
        /// アイテムの配置候補地点。
        /// </summary>
        ItemSpawn = 1 << 4
    }

    #endregion

    #region Maze Cell

    /// <summary>
    /// 迷路内の1マス分のゲームデータを管理する構造体。
    ///
    /// 地形情報と配置物・属性情報を独立して保持する。
    /// GridMapの変更通知に対応するため、
    /// 値型として実装する。
    /// </summary>
    [Serializable]
    public struct MazeCell : IEquatable<MazeCell>
    {
        #region Constants

        /// <summary>
        /// 使用可能なすべての属性フラグ。
        /// 不正なフラグの混入を防止するために使用する。
        /// </summary>
        private const MazeCellFlags ValidFlags =
            MazeCellFlags.Gem |
            MazeCellFlags.Item |
            MazeCellFlags.PlayerSpawn |
            MazeCellFlags.EnemySpawn |
            MazeCellFlags.ItemSpawn;

        #endregion

        #region Fields

        /// <summary>
        /// マスの地形情報。
        /// </summary>
        [SerializeField]
        [Tooltip("マスの地形の種類")]
        private MazeTerrainType terrain;

        /// <summary>
        /// マスが持つ配置物および属性情報。
        /// </summary>
        [SerializeField]
        [Tooltip("マスに設定されている属性フラグ")]
        private MazeCellFlags flags;

        #endregion

        #region Properties

        /// <summary>
        /// 現在の地形情報を取得する。
        /// </summary>
        public MazeTerrainType Terrain => terrain;

        /// <summary>
        /// 現在の属性情報を取得する。
        /// </summary>
        public MazeCellFlags Flags => flags;

        /// <summary>
        /// 通常の床であるかどうか。
        /// </summary>
        public bool IsFloor =>
            terrain == MazeTerrainType.Floor;

        /// <summary>
        /// 通常の壁または破壊可能な壁であるかどうか。
        /// </summary>
        public bool IsWall =>
            terrain == MazeTerrainType.Wall ||
            terrain == MazeTerrainType.BreakableWall;

        /// <summary>
        /// 破壊可能な壁であるかどうか。
        /// </summary>
        public bool IsBreakable =>
            terrain == MazeTerrainType.BreakableWall;

        /// <summary>
        /// 通常のキャラクターが移動可能かどうか。
        /// </summary>
        public bool IsWalkable =>
            terrain == MazeTerrainType.Floor;

        /// <summary>
        /// 宝石が存在するかどうか。
        /// </summary>
        public bool HasGem =>
            HasFlags(MazeCellFlags.Gem);

        /// <summary>
        /// アイテムが存在するかどうか。
        /// </summary>
        public bool HasItem =>
            HasFlags(MazeCellFlags.Item);

        /// <summary>
        /// プレイヤーの出現地点であるかどうか。
        /// </summary>
        public bool IsPlayerSpawn =>
            HasFlags(MazeCellFlags.PlayerSpawn);

        /// <summary>
        /// 敵の出現地点であるかどうか。
        /// </summary>
        public bool IsEnemySpawn =>
            HasFlags(MazeCellFlags.EnemySpawn);

        /// <summary>
        /// アイテムの配置候補地点であるかどうか。
        /// </summary>
        public bool IsItemSpawn =>
            HasFlags(MazeCellFlags.ItemSpawn);

        /// <summary>
        /// 宝石またはアイテムが存在するかどうか。
        /// </summary>
        public bool HasCollectible =>
            HasGem || HasItem;

        /// <summary>
        /// 宝石やアイテムが存在しない移動可能な床かどうか。
        ///
        /// キャラクターの現在位置は考慮しない。
        /// </summary>
        public bool IsEmptyFloor =>
            IsFloor && !HasCollectible;

        /// <summary>
        /// 宝石を新しく配置できるかどうか。
        /// 出現地点や既存の配置物との重複を防止する。
        /// </summary>
        public bool CanPlaceGem =>
            IsWalkable &&
            !HasCollectible &&
            !IsPlayerSpawn &&
            !IsEnemySpawn;

        /// <summary>
        /// アイテムを新しく配置できるかどうか。
        /// アイテム配置候補であるかどうかは考慮しない。
        /// </summary>
        public bool CanPlaceItem =>
            IsWalkable &&
            !HasCollectible &&
            !IsPlayerSpawn &&
            !IsEnemySpawn;

        #endregion

        #region Constructors

        /// <summary>
        /// 指定された地形と属性を持つマスを生成する。
        /// </summary>
        /// <param name="terrain">地形情報</param>
        /// <param name="flags">配置物および属性情報</param>
        public MazeCell(
            MazeTerrainType terrain,
            MazeCellFlags flags = MazeCellFlags.None)
        {
            ValidateTerrain(terrain);

            this.terrain = terrain;

            // 未定義の属性を除外する。
            this.flags = flags & ValidFlags;

            // 壁には配置物や出現地点を設定しない。
            if (terrain != MazeTerrainType.Floor)
            {
                this.flags = MazeCellFlags.None;
            }
        }

        #endregion

        #region Factory Methods

        /// <summary>
        /// 通常の床データを生成する。
        /// </summary>
        /// <param name="flags">床に設定する属性</param>
        /// <returns>生成された床データ</returns>
        public static MazeCell CreateFloor(
            MazeCellFlags flags = MazeCellFlags.None)
        {
            return new MazeCell(
                MazeTerrainType.Floor,
                flags);
        }

        /// <summary>
        /// 通常の壁データを生成する。
        /// </summary>
        /// <returns>生成された壁データ</returns>
        public static MazeCell CreateWall()
        {
            return new MazeCell(
                MazeTerrainType.Wall);
        }

        /// <summary>
        /// 破壊可能な壁データを生成する。
        /// </summary>
        /// <returns>生成された破壊可能な壁データ</returns>
        public static MazeCell CreateBreakableWall()
        {
            return new MazeCell(
                MazeTerrainType.BreakableWall);
        }

        #endregion

        #region Terrain Methods

        /// <summary>
        /// 地形を変更した新しいマスデータを取得する。
        /// 元のマスデータは変更しない。
        ///
        /// 壁へ変更した場合は属性情報を消去する。
        /// </summary>
        /// <param name="newTerrain">変更後の地形</param>
        /// <returns>変更後のマスデータ</returns>
        public MazeCell WithTerrain(
            MazeTerrainType newTerrain)
        {
            return new MazeCell(
                newTerrain,
                flags);
        }

        /// <summary>
        /// 破壊可能な壁を床へ変更する。
        /// 通常の壁や床の場合は変更しない。
        /// </summary>
        /// <returns>壁破壊処理後のマスデータ</returns>
        public MazeCell BreakWall()
        {
            if (!IsBreakable)
            {
                return this;
            }

            return CreateFloor();
        }

        #endregion

        #region Flag Methods

        /// <summary>
        /// 指定された属性をすべて持っているか判定する。
        /// </summary>
        /// <param name="targetFlags">確認対象の属性</param>
        /// <returns>
        /// 指定された属性をすべて持つ場合はtrue
        /// </returns>
        public bool HasFlags(
            MazeCellFlags targetFlags)
        {
            if (targetFlags == MazeCellFlags.None)
            {
                return flags == MazeCellFlags.None;
            }

            return (flags & targetFlags) == targetFlags;
        }

        /// <summary>
        /// 指定された属性のいずれかを持つか判定する。
        /// </summary>
        /// <param name="targetFlags">確認対象の属性</param>
        /// <returns>
        /// 指定された属性のいずれかを持つ場合はtrue
        /// </returns>
        public bool HasAnyFlags(
            MazeCellFlags targetFlags)
        {
            return (flags & targetFlags) != 0;
        }

        /// <summary>
        /// 属性を置き換えた新しいマスデータを取得する。
        /// </summary>
        /// <param name="newFlags">変更後の属性</param>
        /// <returns>変更後のマスデータ</returns>
        public MazeCell WithFlags(
            MazeCellFlags newFlags)
        {
            return new MazeCell(
                terrain,
                newFlags);
        }

        /// <summary>
        /// 指定された属性を追加したマスデータを取得する。
        /// 既存の属性は維持する。
        /// </summary>
        /// <param name="targetFlags">追加する属性</param>
        /// <returns>変更後のマスデータ</returns>
        public MazeCell AddFlags(
            MazeCellFlags targetFlags)
        {
            return WithFlags(flags | targetFlags);
        }

        /// <summary>
        /// 指定された属性を除去したマスデータを取得する。
        /// その他の属性は維持する。
        /// </summary>
        /// <param name="targetFlags">除去する属性</param>
        /// <returns>変更後のマスデータ</returns>
        public MazeCell RemoveFlags(
            MazeCellFlags targetFlags)
        {
            return WithFlags(flags & ~targetFlags);
        }

        /// <summary>
        /// 指定された属性を有効または無効にする。
        /// </summary>
        /// <param name="targetFlags">変更対象の属性</param>
        /// <param name="enabled">有効にする場合はtrue</param>
        /// <returns>変更後のマスデータ</returns>
        public MazeCell SetFlags(
            MazeCellFlags targetFlags,
            bool enabled)
        {
            return enabled
                ? AddFlags(targetFlags)
                : RemoveFlags(targetFlags);
        }

        /// <summary>
        /// すべての属性を消去したマスデータを取得する。
        /// 地形情報は維持する。
        /// </summary>
        /// <returns>属性消去後のマスデータ</returns>
        public MazeCell ClearFlags()
        {
            return WithFlags(MazeCellFlags.None);
        }

        #endregion

        #region Collectible Methods

        /// <summary>
        /// 宝石を配置したマスデータを取得する。
        /// 配置できない場合は元のデータを返す。
        /// </summary>
        /// <returns>宝石配置処理後のマスデータ</returns>
        public MazeCell PlaceGem()
        {
            if (!CanPlaceGem)
            {
                return this;
            }

            return AddFlags(MazeCellFlags.Gem);
        }

        /// <summary>
        /// 宝石を取得した後のマスデータを取得する。
        /// </summary>
        /// <returns>宝石除去後のマスデータ</returns>
        public MazeCell CollectGem()
        {
            return RemoveFlags(MazeCellFlags.Gem);
        }

        /// <summary>
        /// アイテムを配置したマスデータを取得する。
        /// 配置できない場合は元のデータを返す。
        /// </summary>
        /// <returns>アイテム配置処理後のマスデータ</returns>
        public MazeCell PlaceItem()
        {
            if (!CanPlaceItem)
            {
                return this;
            }

            return AddFlags(MazeCellFlags.Item);
        }

        /// <summary>
        /// アイテムを取得した後のマスデータを取得する。
        /// </summary>
        /// <returns>アイテム除去後のマスデータ</returns>
        public MazeCell CollectItem()
        {
            return RemoveFlags(MazeCellFlags.Item);
        }

        /// <summary>
        /// 宝石とアイテムをすべて除去する。
        /// 出現地点などの属性は維持する。
        /// </summary>
        /// <returns>配置物除去後のマスデータ</returns>
        public MazeCell ClearCollectibles()
        {
            return RemoveFlags(
                MazeCellFlags.Gem |
                MazeCellFlags.Item);
        }

        #endregion

        #region Validation Methods

        /// <summary>
        /// 指定された地形が有効な値か確認する。
        /// 不正な値の場合は例外を発生させる。
        /// </summary>
        /// <param name="targetTerrain">確認対象の地形</param>
        private static void ValidateTerrain(
            MazeTerrainType targetTerrain)
        {
            switch (targetTerrain)
            {
                case MazeTerrainType.Floor:
                case MazeTerrainType.Wall:
                case MazeTerrainType.BreakableWall:
                    return;

                default:
                    throw new ArgumentOutOfRangeException(
                        nameof(targetTerrain),
                        targetTerrain,
                        "未定義の地形が指定されました。");
            }
        }

        #endregion

        #region Equality Methods

        /// <summary>
        /// 他のマスデータと内容が一致するか確認する。
        /// </summary>
        /// <param name="other">比較対象のマスデータ</param>
        /// <returns>内容が一致する場合はtrue</returns>
        public bool Equals(MazeCell other)
        {
            return terrain == other.terrain &&
                   flags == other.flags;
        }

        /// <summary>
        /// 指定されたオブジェクトと内容が一致するか確認する。
        /// </summary>
        /// <param name="obj">比較対象のオブジェクト</param>
        /// <returns>内容が一致する場合はtrue</returns>
        public override bool Equals(object obj)
        {
            return obj is MazeCell other &&
                   Equals(other);
        }

        /// <summary>
        /// マスデータのハッシュ値を取得する。
        /// </summary>
        /// <returns>地形と属性から算出したハッシュ値</returns>
        public override int GetHashCode()
        {
            unchecked
            {
                return ((int)terrain * 397) ^
                       (int)flags;
            }
        }

        /// <summary>
        /// 2つのマスデータが等しいか判定する。
        /// </summary>
        /// <param name="left">左辺のマスデータ</param>
        /// <param name="right">右辺のマスデータ</param>
        /// <returns>等しい場合はtrue</returns>
        public static bool operator ==(
            MazeCell left,
            MazeCell right)
        {
            return left.Equals(right);
        }

        /// <summary>
        /// 2つのマスデータが異なるか判定する。
        /// </summary>
        /// <param name="left">左辺のマスデータ</param>
        /// <param name="right">右辺のマスデータ</param>
        /// <returns>異なる場合はtrue</returns>
        public static bool operator !=(
            MazeCell left,
            MazeCell right)
        {
            return !left.Equals(right);
        }

        #endregion

        #region Debug Methods

        /// <summary>
        /// マスデータの内容を文字列として取得する。
        /// デバッグログなどに使用する。
        /// </summary>
        /// <returns>地形と属性を表す文字列</returns>
        public override string ToString()
        {
            return $"Terrain: {terrain}, Flags: {flags}";
        }

        #endregion
    }

    #endregion
}
